// app.jsx — Main App Epona shell
import React, { useState, useEffect } from 'react';
import { IOSDevice, IOSStatusBar } from './ios-frame';
import { useTweaks, TweaksPanel, TweakSection, TweakRadio, TweakSelect } from './tweaks-panel';
import { CAVALOS, PROPRIETARIOS, REGISTROS_HOJE, AVISOS, MOVIMENTACOES, INSUMOS } from './data';
import { AddInsumoScreen, EditarInsumoScreen } from './insumo-form';
import {
  HomeScreen, CavalosScreen, CavaloDetalheScreen, EditarCavaloScreen, AddCavaloScreen,
  ProprietarioScreen,
  CadastrosScreen, CadProprietariosScreen, CadInsumosScreen, CadMensalidadesScreen, CadCavalosScreen,
  FaturasScreen, FaturaDetalheScreen,
  TabBar, OperacionalTabBar,
} from './screens';
import { AvisosScreen, MovimentacaoScreen } from './extra-screens';
import { RegistrarHub, RegistrarPorCavalo, RegistrarPorInsumo, RegistrarPorSetor } from './register';
import { LoginScreen, ROLE_COLORS } from './auth';
import { NutricionalScreen } from './nutricional';

const TWEAKS_DEFAULTS = /*EDITMODE-BEGIN*/{
  "density": "comfortable",
  "defaultFlow": "cavalo"
}/*EDITMODE-END*/;

function AppEpona() {
  const [currentUser, setCurrentUser] = useState(null);
  const [tab, setTab] = useState('home');
  const [screen, setScreen] = useState('home'); // home, cavalos, cavaloDetalhe, registrar, cadastros, etc
  const [selected, setSelected] = useState(null);
  const [cavalos, setCavalos] = useState(CAVALOS);
  const [proprietarios, setProprietarios] = useState(PROPRIETARIOS);
  const [registros, setRegistros] = useState(REGISTROS_HOJE);
  const [avisos, setAvisos] = useState(AVISOS);
  const [movimentacoes, setMovimentacoes] = useState(MOVIMENTACOES);
  const [novoCavaloPendente, setNovoCavaloPendente] = useState(null);
  const [pendingEntradaCavalo, setPendingEntradaCavalo] = useState(false);
  const [insumos, setInsumos] = useState(INSUMOS);
  const [fluxo, setFluxo] = useState(null);
  const [tweaks, setTweak] = useTweaks(TWEAKS_DEFAULTS);

  const handleLogin = (user) => {
    setCurrentUser(user);
    if (user.role === 'operacional') {
      setScreen('avisos');
      setTab('avisos');
    } else {
      setScreen('home');
      setTab('home');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setScreen('home');
    setTab('home');
  };

  const addRegistro = (r) => setRegistros(prev => [...prev, r]);
  const addInsumo = (ins) => setInsumos(prev => [...prev, ins]);
  const updateInsumo = (id, data) => setInsumos(prev => prev.map(i => i.id === id ? { ...i, ...data } : i));
  const addAviso = (a) => setAvisos(prev => [a, ...prev]);
  const addMovimentacao = (m) => setMovimentacoes(prev => [...prev, m]);

  const updateCavalo = (id, updatedData) => {
    setCavalos(prev => prev.map(c => c.id === id ? { ...c, ...updatedData } : c));
  };

  const deleteCavalo = (id) => {
    setCavalos(prev => prev.filter(c => c.id !== id));
  };

  const addProprietario = (nome) => {
    const maxId = Math.max(...proprietarios.map(p => parseInt(p.id.substring(1))));
    const newId = 'p' + (maxId + 1);
    const novoProp = { id: newId, nome, telefone: '', email: '', cavalos: [] };
    setProprietarios(prev => [...prev, novoProp]);
    return newId;
  };

  const updateProprietario = (id, updatedData) => {
    setProprietarios(prev => prev.map(p => p.id === id ? { ...p, ...updatedData } : p));
  };

  // Aviso diário de almoço — gerado uma vez por dia na inicialização
  useEffect(() => {
    const today = new Date().toDateString();
    const lastDate = localStorage.getItem('epona_almoco_date');
    if (lastDate !== today) {
      const almocoCavalos = cavalos.filter(c => c.nutricao?.comeAlmoco);
      if (almocoCavalos.length > 0) {
        const linhas = almocoCavalos.map(c => {
          const racaoNome = INSUMOS.find(i => i.id === c.nutricao.racaoId)?.nome || '';
          return `• ${c.nome}: ${c.nutricao.racaoKgAlmoco ?? 0} kg de ${racaoNome}`;
        }).join('\n');
        addAviso({
          id: 'almoco_' + Date.now(),
          autor: 'Sistema', avatar: 'SYS', tempo: 'hoje',
          texto: `🍽️ Trato do almoço — ${almocoCavalos.length} ${almocoCavalos.length === 1 ? 'animal' : 'animais'}:\n${linhas}`,
        });
      }
      localStorage.setItem('epona_almoco_date', today);
    }
  }, []);

  // Sync tab → screen
  useEffect(() => {
    if (tab === 'home') setScreen('home');
    if (tab === 'cavalos') setScreen('cavalos');
    if (tab === 'cadastros') setScreen('cadastros');
    if (tab === 'faturas') setScreen('faturas');
    if (tab === 'nutricional') setScreen('nutricional');
    if (tab === 'avisos') setScreen('avisos');
  }, [tab]);

  // Quando entra em registrar, usa fluxo padrão dos tweaks
  useEffect(() => {
    if (screen === 'registrar' && !fluxo) {
      setFluxo(tweaks.defaultFlow);
    }
    if (screen !== 'registrar') {
      setFluxo(null);
    }
  }, [screen]);

  const goScreen = (s) => {
    if (currentUser?.role === 'operacional' && !['avisos', 'nutricional'].includes(s)) return;
    if (currentUser?.role === 'vet' && ['faturas', 'faturaDetalhe'].includes(s)) return;
    setScreen(s);
    if (s === 'home') setTab('home');
    if (s === 'cavalos' || s === 'addCavalo') setTab('cavalos');
    if (s === 'cadastros' || s.startsWith('cad') || s === 'addInsumo' || s === 'editarInsumo') setTab('cadastros');
    if (s === 'faturas' || s === 'faturaDetalhe') setTab('faturas');
    if (s === 'avisos') setTab('avisos');
    if (s === 'nutricional') setTab('nutricional');
  };

  let content;
  if (!currentUser) {
    content = <LoginScreen onLogin={handleLogin} />;
  } else if (screen === 'home') content = <HomeScreen registros={registros} setScreen={goScreen} density={tweaks.density} avisos={avisos} />;
  else if (screen === 'avisos') content = <AvisosScreen setScreen={goScreen} avisos={avisos} addAviso={addAviso} currentUser={currentUser} />;
  else if (screen === 'nutricional') content = <NutricionalScreen setScreen={goScreen} setSelected={setSelected} cavalos={cavalos} insumos={insumos} currentUser={currentUser} />;
  else if (screen === 'movimentacao') content = <MovimentacaoScreen setScreen={goScreen} addMovimentacao={addMovimentacao} addAtividade={addAviso} cavalos={cavalos} proprietarios={proprietarios} novoCavaloPendente={novoCavaloPendente} setNovoCavaloPendente={setNovoCavaloPendente} setPendingEntradaCavalo={setPendingEntradaCavalo} />;
  else if (screen === 'cavalos') content = <CavalosScreen setScreen={goScreen} setSelected={setSelected} density={tweaks.density} cavalos={cavalos} setCavalos={setCavalos} proprietarios={proprietarios} />;
  else if (screen === 'addCavalo') content = <AddCavaloScreen setScreen={goScreen} setCavalos={setCavalos} cavalos={cavalos} setNovoCavaloPendente={setNovoCavaloPendente} pendingEntradaCavalo={pendingEntradaCavalo} setPendingEntradaCavalo={setPendingEntradaCavalo} proprietarios={proprietarios} addProprietario={addProprietario} />;
  else if (screen === 'cavaloDetalhe') content = <CavaloDetalheScreen id={selected} setScreen={goScreen} registros={registros} setSelected={setSelected} cavalos={cavalos} updateCavalo={updateCavalo} deleteCavalo={deleteCavalo} proprietarios={proprietarios} />;
  else if (screen === 'editarCavalo') content = <EditarCavaloScreen id={selected} setScreen={goScreen} cavalos={cavalos} updateCavalo={updateCavalo} deleteCavalo={deleteCavalo} proprietarios={proprietarios} addAviso={addAviso} currentUser={currentUser} />;
  else if (screen === 'proprietarioDetalhe') content = <ProprietarioScreen id={selected} setScreen={goScreen} proprietarios={proprietarios} cavalos={cavalos} updateProprietario={updateProprietario} />;
  else if (screen === 'cadastros') content = <CadastrosScreen setScreen={goScreen} />;
  else if (screen === 'cadProprietarios') content = <CadProprietariosScreen setScreen={goScreen} setSelected={setSelected} proprietarios={proprietarios} cavalos={cavalos} addProprietario={addProprietario} />;
  else if (screen === 'cadCavalos') content = <CadCavalosScreen setScreen={goScreen} setSelected={setSelected} cavalos={cavalos} deleteCavalo={deleteCavalo} proprietarios={proprietarios} />;
  else if (screen === 'cadInsumos') content = <CadInsumosScreen setScreen={goScreen} setSelected={setSelected} insumos={insumos} addInsumo={addInsumo} updateInsumo={updateInsumo} />;
  else if (screen === 'addInsumo') content = <AddInsumoScreen setScreen={goScreen} addInsumo={addInsumo} insumos={insumos} />;
  else if (screen === 'editarInsumo') content = <EditarInsumoScreen id={selected} setScreen={goScreen} insumos={insumos} updateInsumo={updateInsumo} />;
  else if (screen === 'cadMensalidades') content = <CadMensalidadesScreen setScreen={goScreen} />;
  else if (screen === 'faturas') content = <FaturasScreen setScreen={goScreen} setSelected={setSelected} registros={registros} insumos={insumos} />;
  else if (screen === 'faturaDetalhe') content = <FaturaDetalheScreen id={selected} setScreen={goScreen} registros={registros} proprietarios={proprietarios} insumos={insumos} />;
  else if (screen === 'registrar') {
    if (!fluxo) content = <RegistrarHub setScreen={goScreen} setFluxo={setFluxo} />;
    else if (fluxo === 'cavalo') content = <RegistrarPorCavalo setScreen={goScreen} addRegistro={addRegistro} insumos={insumos} />;
    else if (fluxo === 'insumo') content = <RegistrarPorInsumo setScreen={goScreen} addRegistro={addRegistro} insumos={insumos} />;
    else if (fluxo === 'setor') content = <RegistrarPorSetor setScreen={goScreen} addRegistro={addRegistro} insumos={insumos} />;
  }

  const isOperacional = currentUser?.role === 'operacional';
  const showMainTabs = currentUser && !isOperacional && ['home', 'cavalos', 'cadastros', 'faturas', 'nutricional'].includes(screen);
  const showOperacionalTabs = isOperacional && ['avisos', 'nutricional'].includes(screen);

  return (
    <>
      <IOSDevice color="space-black" hasDynamicIsland={false} time="06:42">
        <div data-screen-label={`App · ${screen}`} style={{
          position: 'absolute', inset: 0,
          background: 'var(--bg)', overflow: 'hidden',
          fontFamily: 'var(--sans)',
          display: 'flex', flexDirection: 'column',
        }}>
          <IOSStatusBar dark={false} time="06:42" />
          <div style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', position: 'relative' }}>
            {/* User badge overlay */}
            {currentUser && (
              <div style={{
                position: 'absolute', top: 8, right: 12, zIndex: 100,
                background: 'rgba(255,255,255,0.92)', borderRadius: 20,
                padding: '4px 10px 4px 5px',
                display: 'flex', alignItems: 'center', gap: 6,
                backdropFilter: 'blur(8px)',
                border: '1px solid var(--line)',
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
              }}>
                <div style={{
                  width: 24, height: 24, borderRadius: 12,
                  background: ROLE_COLORS[currentUser.role], color: '#fff',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 9, fontWeight: 700, letterSpacing: '-0.02em',
                }}>
                  {currentUser.iniciais}
                </div>
                <span style={{ fontSize: 11, color: 'var(--ink)', fontWeight: 600 }}>
                  {currentUser.nome.split(' ')[0]}
                </span>
                <button onClick={handleLogout} style={{
                  background: 'none', border: 'none', padding: '0 0 0 2px', cursor: 'pointer',
                  fontSize: 10, color: 'var(--ink-3)', fontFamily: 'var(--sans)',
                }}>
                  sair
                </button>
              </div>
            )}
            {content}
          </div>
          {showMainTabs && <TabBar tab={tab} setTab={setTab} role={currentUser?.role} />}
          {showOperacionalTabs && <OperacionalTabBar tab={tab} setTab={setTab} />}
        </div>
      </IOSDevice>

      <TweaksPanel title="Tweaks">
        <TweakSection title="Densidade da informação">
          <TweakRadio
            value={tweaks.density}
            onChange={(v) => setTweak('density', v)}
            options={[
              { value: 'compact', label: 'Compacta' },
              { value: 'comfortable', label: 'Confortável' },
            ]}
          />
        </TweakSection>
        <TweakSection title="Fluxo de registro padrão">
          <TweakSelect
            value={tweaks.defaultFlow}
            onChange={(v) => setTweak('defaultFlow', v)}
            options={[
              { value: 'cavalo', label: 'Por cavalo (1 cavalo → vários insumos)' },
              { value: 'insumo', label: 'Por insumo (1 insumo → vários cavalos)' },
              { value: 'setor', label: 'Por setor (lote rápido)' },
            ]}
          />
          <div style={{ fontSize: 11, color: '#888', marginTop: 6 }}>
            Determina qual fluxo abre quando o tratador toca em "Registrar insumo".
          </div>
        </TweakSection>
      </TweaksPanel>
    </>
  );
}

export default AppEpona;
